# Not autogenerated.
"""Check the Feather benchmark workload and its output cleanup."""

# ruff: noqa: S101, D103
import subprocess
import sys
from collections.abc import Iterator
from contextlib import contextmanager
from pathlib import Path
from struct import pack
from tempfile import TemporaryDirectory

import polars as pl
import pytest

from benchmarks import bench
from lobo.replay.adapters import itch


@pytest.fixture
def itch_file(tmp_path: Path) -> Path:
    def message(tag: bytes, locate: int, body: bytes) -> bytes:
        return pack(">HcHH6s", len(body) + 11, tag, locate, 0, bytes(6)) + body

    messages = []
    for locate, stock in ((1, b"AAPL    "), (2, b"MSFT    ")):
        messages.append(
            message(
                b"R",
                locate,
                pack(
                    ">8sccIcc2scccccIc",
                    stock,
                    b"Q",
                    b"N",
                    100,
                    b"N",
                    b"C",
                    b"C ",
                    b"P",
                    b"N",
                    b"N",
                    b"1",
                    b"N",
                    1,
                    b"N",
                ),
            )
        )
        messages.append(
            message(b"A", locate, pack(">QcI8sI", locate, b"B", 100, stock, 10000))
        )
    messages.append(message(b"D", 1, pack(">Q", 1)))
    # This final record must be replayed as well as both tickers' add messages.
    messages.append(message(b"X", 2, pack(">QI", 2, 25)))
    path = tmp_path / "full.itch"
    path.write_bytes(b"".join(messages))
    return path


@pytest.mark.parametrize("concurrent", [False, True])
@pytest.mark.parametrize("aapl_only", [False, True])
def test_feather_benchmark_deletes_its_files(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
    itch_file: Path,
    *,
    concurrent: bool,
    aapl_only: bool,
) -> None:
    directories = []
    frames = []
    sizes = []

    @contextmanager
    def directory(*, prefix: str, dir: str | None = None) -> Iterator[str]:
        assert dir is None
        with TemporaryDirectory(prefix=prefix, dir=tmp_path) as name:
            directories.append(Path(name))
            yield name
            output = Path(name) / "updates.feather"
            sizes.append(output.stat().st_size)
            frames.append(pl.read_ipc(output))

    monkeypatch.setattr(bench, "TemporaryDirectory", directory)
    sources = (
        itch.ItchSource(str(itch_file), "AAPL")
        if aapl_only
        else itch.ItchSource.all_available(str(itch_file))
    )
    result = bench.replay_to_feather(sources, 2, 4096, concurrent=concurrent)
    assert result.rows == (2 if aapl_only else 4)
    assert result.file_bytes == sizes[0] > 0
    assert result.batches == (1 if aapl_only else 2)
    assert result.replay_seconds > 0
    assert result.drain_seconds > 0
    updates = frames[0]
    assert updates["book_id"].n_unique() == (1 if aapl_only else 2)
    for quantities in updates.partition_by("book_id"):
        assert quantities["visible_quantity"].to_list() in ([100, 0], [100, 75])
    assert sorted(updates["visible_quantity"].to_list()) == (
        [0, 100] if aapl_only else [0, 75, 100, 100]
    )
    assert directories
    assert all(not path.exists() for path in directories)
    assert list(tmp_path.iterdir()) == [itch_file]


def test_feather_benchmark_prints_output_statistics(
    itch_file: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    elapsed = bench.time_replay_to_feather(
        1, itch.ItchSource.all_available(str(itch_file)), 2, 4096, concurrent=False
    )
    assert elapsed > 0
    output = capsys.readouterr().out
    assert "Feather output per replay: 4 rows | " in output
    assert " bytes (" in output
    assert "2 batches | file deleted" in output
    assert "setup/replay" in output
    assert "drain/finalize after replay" in output


def test_feather_benchmark_cleans_up_after_failure(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, itch_file: Path
) -> None:
    def directory(*, prefix: str, dir: str | None = None) -> TemporaryDirectory[str]:
        assert dir is None
        return TemporaryDirectory(prefix=prefix, dir=tmp_path)

    monkeypatch.setattr(bench, "TemporaryDirectory", directory)
    sources = itch.ItchSource.all_available(str(itch_file))
    itch_file.unlink()
    with pytest.raises(RuntimeError):
        bench.replay_to_feather(sources, 128, 4096)
    assert list(tmp_path.iterdir()) == []


def test_parent_removes_partial_output_after_worker_timeout(
    tmp_path: Path, itch_file: Path
) -> None:
    marker = tmp_path / "partial-path.txt"
    script = tmp_path / "timeout_benchmark.py"
    python_root = Path(bench.__file__).resolve().parents[1]
    script.write_text(
        f"""import sys
from pathlib import Path
from time import sleep
sys.path.insert(0, {str(python_root)!r})
from benchmarks import bench

def stalled_replay(*args, output_directory, **kwargs):
    output = Path(output_directory) / "unfinished.feather"
    output.write_bytes(b"partial benchmark output")
    Path({str(marker)!r}).write_text(str(output))
    sleep(30)

bench.replay_to_feather = stalled_replay
bench.main()
"""
    )
    result = subprocess.run(  # noqa: S603 -- local benchmark and generated fixture
        [
            sys.executable,
            str(script),
            "--scenario",
            "feather-single-threaded",
            "--itch-path",
            str(itch_file),
            "--processes",
            "1",
            "--values",
            "1",
            "--warmups",
            "0",
            "--loops",
            "1",
            "--timeout",
            "2",
        ],
        capture_output=True,
        text=True,
        timeout=15,
        check=False,
    )
    assert result.returncode == 124, result.stdout + result.stderr
    assert "Timed out after 2 seconds" in result.stdout
    output = Path(marker.read_text())
    assert not output.exists()
    assert not output.parent.exists()
